// packages/core/src/index.ts
export type AsyncState<T> =
  | { kind: 'idle' }
  | { kind: 'loading'; startedAt: number }
  | { kind: 'success'; data: T }
  | { kind: 'error'; reason: string };
export type Event<T> = { type: 'start'; at: number } | { type: 'resolve'; data: T } | { type: 'reject'; reason: string };
export function transition<T>(state: AsyncState<T>, event: Event<T>): AsyncState<T> {
  switch (event.type) {
    case 'start': return { kind: 'loading', startedAt: event.at };
    case 'resolve': return state.kind === 'loading' ? { kind: 'success', data: event.data } : state;
    case 'reject': return state.kind === 'loading' ? { kind: 'error', reason: event.reason } : state;
    default: { const exhaustive: never = event; return exhaustive; }
  }
}
